import fs from 'node:fs';
const repo=process.env.GITHUB_REPOSITORY;
if(repo!=='mohanad-hafez/mcp-adr-analysis-server-checks')throw Error('Unexpected publish target');
const file='esm-evidence/publication.json';
if(fs.existsSync(file))throw Error('Prior delivery receipt exists; inspect before replay');
const result=JSON.parse(fs.readFileSync('esm-evidence/result.json','utf8'));
if(result.controlled_expectation_matched!==true)throw Error('Oracle mismatch');
if(result.passed){fs.writeFileSync(file,JSON.stringify({status:'no_issue_required',writes:0})+'\n');process.exit(0)}
const grouped=new Map();for(const x of result.static.findings){if(!grouped.has(x.type))grouped.set(x.type,[]);grouped.get(x.type).push(x)}
const files=new Set(result.static.findings.map(x=>x.file));
const title=result.static.findings.length ? `[esm-validation] ESM violations in ${files.size} file(s)` : '[esm-validation] Native validation gate failure';
const safe=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('`','&#96;').replaceAll('|','&#124;');
const body=['## ESM Module Validation Failure','','### Violations Found','','| Type | Count | Files |','| --- | ---: | --- |',...[...grouped].map(([type,rows])=>`| ${type} | ${rows.length} | ${[...new Set(rows.map(x=>x.file))].map(x=>'`'+safe(x)+'`').join(', ')} |`),'','### Detailed Findings','',...result.static.findings.map(x=>`- \`${safe(x.file)}:${x.line}\` — ${x.type}: \`${safe(x.code)}\``),'','### How to Fix','','Use relative `.js` import paths, ES module imports/exports, and `getCurrentDirCompat(import.meta.url)` for directory resolution.','','### Native runtime gates','','| Gate | Exit code | Signal |','| --- | --- | --- |',...result.gates.map(x=>`| ${x.name} | ${x.exit_code??'none'} | ${x.signal??'none'} |`),'','Nonzero native gates require inspection of the corresponding artifact logs; a nonzero gate alone does not establish an ESM-specific cause.','',`[Workflow run and detailed log artifacts](https://github.com/${repo}/actions/runs/${process.env.GITHUB_RUN_ID})`,'','_Generated by ESM Module Validation workflow_'].join('\n');
const receipt={status:'delivery_started',title,body,run_id:process.env.GITHUB_RUN_ID,scenario:result.scenario};
fs.writeFileSync(file,JSON.stringify(receipt,null,2)+'\n');
try{
 const response=await fetch(`https://api.github.com/repos/${repo}/issues`,{method:'POST',headers:{Authorization:`Bearer ${process.env.GITHUB_TOKEN}`,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','Content-Type':'application/json'},body:JSON.stringify({title,body}),signal:AbortSignal.timeout(30000),redirect:'error'});
 receipt.http_status=response.status;if(!response.ok)throw Error('Issue publication HTTP '+response.status);
 const issue=await response.json();receipt.status='created';receipt.issue_number=issue.number;receipt.issue_url=issue.html_url;
}catch(e){receipt.status='delivery_uncertain';receipt.error=e.message;throw e}
finally{fs.writeFileSync(file,JSON.stringify(receipt,null,2)+'\n')}
